import type { ComponentType, SVGProps } from "react"

import * as icons from "./icons/chrome"

const chromeIcons = {
  search: icons.Search,
  close: icons.Close,
  menu: icons.Menu,
  "sidebar-toggle": icons.SidebarToggle,
  "light-theme": icons.LightTheme,
  "dark-theme": icons.DarkTheme,
  "system-theme": icons.SystemTheme,
  language: icons.Language,
  "external-link": icons.ExternalLink,
  chevron: icons.Chevron,
  "previous-next": icons.PreviousNext,
  tip: icons.Tip,
  info: icons.Info,
  note: icons.Note,
  warning: icons.Warning,
  danger: icons.Danger,
  copy: icons.Copy,
  copied: icons.Copied,
  edit: icons.Edit,
  "last-updated": icons.LastUpdated,
  "heading-link": icons.HeadingLink,
} satisfies Record<string, ComponentType<SVGProps<SVGSVGElement>>>

type ChromeIconName = keyof typeof chromeIcons

type ChromeIconProps = {
  name: ChromeIconName
  size?: number
} & Omit<SVGProps<SVGSVGElement>, "children">

export function ChromeIcon({ name, size = 14, ...props }: ChromeIconProps) {
  const Icon = chromeIcons[name]
  return <Icon {...props} width={size} height={size} aria-hidden="true" data-chrome-icon={name} />
}
